import { useEffect, useMemo, useState } from "react";

type View = "Overview" | "Keywords" | "Keyword Gap" | "Competitors" | "Rank Tracker" | "Backlinks" | "Site Audit" | "On-Page SEO" | "Topic Research" | "Writing Assistant" | "Content Briefs" | "Reports" | "Integrations";
type Status = { pageSpeed: boolean; searchConsole: boolean; analytics: boolean; seoData: boolean };
type Keyword = { keyword: string; intent: string; volume: number; difficulty: number; cpc: number; competition: number };
type Competitor = { domain: string; intersections: number; traffic: number; keywords: number; averagePosition: number };
type RefDomain = { domain: string; rank: number; backlinks: number; dofollow: number; firstSeen: string };
type BacklinkSummary = { rank: number; backlinks: number; referringDomains: number; referringPages: number; brokenBacklinks: number };
type GapKeyword = { keyword: string; intent: string; volume: number; difficulty: number; cpc: number; competitorPosition: number };
type PageSpeedData = { source: string; fallback?: boolean; notice?: string; strategy: string; url: string; fetchedAt: string; scores: { performance: number | null; accessibility: number | null; bestPractices: number | null; seo: number | null }; metrics: { lcp: string; cls: string; tbt: string }; opportunities: { id: string; title: string; detail: string; score: number | null }[] };
type GoogleData = { gsc?: { summary: { clicks: number; impressions: number; ctr: number; position: number }; rows: Array<{ query: string; clicks: number; impressions: number; ctr: number; position: number }> }; ga?: { summary: { sessions: number; engagedSessions: number; engagementRate: number; keyEvents: number }; rows: Array<{ page: string; sessions: number; engagedSessions: number; keyEvents: number }> } };
type OnPageResult = { source: string; analysedAt: string; url: string; score: number; title: string; description: string; h1s: string[]; metrics: { words: number; h2Count: number; images: number; imagesWithAlt: number; internalLinks: number; externalLinks: number; keywordUses: number }; technical: { canonical: string; robots: string; hasViewport: boolean }; checks: Array<{ category: string; title: string; detail: string; passed: boolean; impact: "High" | "Medium" | "Low" }> };
type RankHistoryEntry = { domain: string; keyword: string; position: number | null; url: string; checkedAt: string; source: "live" | "demo" };
type WorkspaceSnapshot = { domain: string; keywords: Keyword[]; competitors: Competitor[]; backlinks: BacklinkSummary; refDomains: RefDomain[]; google?: GoogleData; rankHistory?: RankHistoryEntry[] };

