function compact(value: number) { return Intl.NumberFormat("en", { notation: "compact", maximumFractionDigits: 1 }).format(value || 0); }
function cleanDomain(value: string) { return value.trim().replace(/^https?:\/\//i, "").replace(/^www\./i, "").split("/")[0] || "northstar.io"; }
function csv(name: string, headers: (string | number)[], rows: (string | number)[][]) {
  const escape = (value: string | number) => `"${String(value).replaceAll('"', '""')}"`;
  const blob = new Blob([[headers, ...rows].map((row) => row.map(escape).join(",")).join("\n")], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url);
}

function TrendChart() {
  return <div className="trend-chart" aria-label="Organic search performance trend"><div className="chart-grid"><span /><span /><span /><span /></div><svg viewBox="0 0 700 210" preserveAspectRatio="none" role="img" aria-hidden="true"><defs><linearGradient id="trafficFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#ff6b4a" stopOpacity=".28" /><stop offset="100%" stopColor="#ff6b4a" stopOpacity="0" /></linearGradient></defs><path className="chart-area" d="M0,174 C48,165 74,177 108,155 C143,132 169,148 208,127 C253,103 275,123 316,105 C352,89 372,98 410,74 C443,55 467,78 504,59 C545,38 569,52 607,31 C642,12 670,28 700,12 L700,210 L0,210 Z" /><path className="chart-line" d="M0,174 C48,165 74,177 108,155 C143,132 169,148 208,127 C253,103 275,123 316,105 C352,89 372,98 410,74 C443,55 467,78 504,59 C545,38 569,52 607,31 C642,12 670,28 700,12" /><circle cx="607" cy="31" r="6" /></svg><div className="chart-labels"><span>Week 1</span><span>Week 2</span><span>Week 3</span><span>Week 4</span></div></div>;
}
function SourceNote({ live, children }: { live: boolean; children?: React.ReactNode }) { return <div className={live ? "source-note live" : "source-note demo"}><span>{live ? "LIVE" : "DEMO"}</span><p>{children || (live ? "Connected provider data" : "Interactive sample data until a provider is connected")}</p></div>; }

function Overview({ domain, period, setPeriod, status, google, syncing, syncError, sync }: { domain: string; period: string; setPeriod: (value: string) => void; status: Status | null; google: GoogleData; syncing: boolean; syncError: string; sync: () => void }) {
  const live = Boolean(google.ga || google.gsc); const traffic = google.ga?.summary.sessions ?? 24800; const clicks = google.gsc?.summary.clicks ?? 4281; const impressions = google.gsc?.summary.impressions ?? 184600;
  return <><section className="summary-row"><div><div className="eyebrow"><span className={live ? "live-dot" : "demo-dot"} /> Domain overview <span className={live ? "live-chip" : "demo-chip"}>{live ? "Google data" : "Demo data"}</span></div><h1>{domain}</h1><p className="subtle">Organic search workspace · Ireland</p></div><div className="summary-actions"><div className="period-switch" aria-label="Select reporting period">{["7D", "30D", "3M", "12M"].map((item) => <button key={item} className={period === item ? "active" : ""} onClick={() => setPeriod(item)}>{item}</button>)}</div>{(status?.analytics || status?.searchConsole) && <button className="sync-button" onClick={sync} disabled={syncing}>{syncing ? "Syncing…" : "Sync Google data"}</button>}</div></section>{syncError && <div className="audit-message error-message" role="alert"><b>Google sync unavailable</b><span>{syncError}</span></div>}<section className="metric-grid"><article className="metric-card"><div className="metric-top"><span>Organic sessions</span><span className={live ? "live-source" : "demo-chip"}>{live ? "GA4" : "DEMO"}</span></div><strong>{compact(traffic)}</strong><p><b>+18.4%</b> vs previous period</p></article><article className="metric-card"><div className="metric-top"><span>Search clicks</span><span className={live ? "live-source" : "demo-chip"}>{live ? "GSC" : "DEMO"}</span></div><strong>{compact(clicks)}</strong><p><b>+236</b> in selected period</p></article><article className="metric-card"><div className="metric-top"><span>Impressions</span><span className={live ? "live-source" : "demo-chip"}>{live ? "GSC" : "DEMO"}</span></div><strong>{compact(impressions)}</strong><p>Average position {google.gsc?.summary.position.toFixed(1) || "18.6"}</p></article><article className="metric-card"><div className="metric-top"><span>Key events</span><span className={live ? "live-source" : "demo-chip"}>{live ? "GA4" : "DEMO"}</span></div><strong>{compact(google.ga?.summary.keyEvents ?? 386)}</strong><p>Engagement {((google.ga?.summary.engagementRate ?? .684) * 100).toFixed(1)}%</p></article></section><section className="dashboard-grid"><article className="panel traffic-panel"><div className="panel-head"><div><span className="panel-kicker">ORGANIC PERFORMANCE</span><h2>Visibility is trending up</h2></div><div className="chart-legend"><span /> Selected period</div></div><div className="chart-total"><strong>{compact(traffic)}</strong><span>organic sessions</span></div><TrendChart /></article><article className="panel health-panel"><div className="panel-head"><div><span className="panel-kicker">SITE HEALTH</span><h2>Technical audit</h2></div></div><div className="health-content"><div className="health-ring"><div><strong>86</strong><span>/100</span></div></div><div className="issue-list"><div><span className="severity error" /> Errors <b>7</b></div><div><span className="severity warning" /> Warnings <b>42</b></div><div><span className="severity notice" /> Notices <b>118</b></div></div></div></article></section><SourceNote live={live}>{live ? "The dashboard is using your connected Google properties." : "Connect GA4 and Search Console to replace overview estimates with owned-site data."}</SourceNote></>;
}

function KeywordsView({ connected, items, setItems }: { connected: boolean; items: Keyword[]; setItems: (value: Keyword[]) => void }) {
  const [seed, setSeed] = useState("project management software"); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const [live, setLive] = useState(false);
  async function research(event: React.FormEvent) { event.preventDefault(); setError(""); if (!connected) { const suffixes = ["", " tools", " for teams", " pricing", " guide"]; setItems(demoKeywords.map((item, index) => ({ ...item, keyword: `${seed}${suffixes[index]}` }))); setLive(false); return; } setLoading(true); try { const response = await fetch(`/api/seo/keywords?keyword=${encodeURIComponent(seed)}`); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || "Keyword research failed."); setItems(payload.items); setLive(true); } catch (cause) { setError(cause instanceof Error ? cause.message : "Keyword research failed."); } finally { setLoading(false); } }
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">KEYWORD INTELLIGENCE</span><h1>Find keywords worth winning</h1><p>Compare demand, ranking difficulty, intent and commercial value for the Irish market.</p></div></div><form className="tool-search" onSubmit={research}><input value={seed} onChange={(event) => setSeed(event.target.value)} aria-label="Seed keyword" minLength={3} placeholder="Enter a seed keyword" /><button disabled={loading}>{loading ? "Researching…" : "Research keywords"}</button></form>{error && <div className="audit-message error-message"><b>Research unavailable</b><span>{error}</span></div>}<SourceNote live={live}>{connected ? (live ? "Current DataForSEO keyword data for Ireland." : "Run a search to retrieve live DataForSEO results.") : "Searches work in sample mode now; add DataForSEO credentials later for live volumes and difficulty."}</SourceNote><article className="panel data-panel"><div className="panel-head"><div><span className="panel-kicker">KEYWORD RESULTS</span><h2>{items.length} opportunities</h2></div><button className="text-button" onClick={() => csv("rankscope-keywords.csv", ["Keyword", "Intent", "Volume", "Difficulty", "CPC", "Competition"], items.map((item) => [item.keyword, item.intent, item.volume, item.difficulty, item.cpc, item.competition]))}>Export CSV</button></div><div className="table-wrap"><table><thead><tr><th>Keyword</th><th>Intent</th><th>Volume</th><th>Difficulty</th><th>CPC</th><th>Competition</th></tr></thead><tbody>{items.map((item) => <tr key={item.keyword}><td data-label="Keyword"><b>{item.keyword}</b></td><td data-label="Intent"><span className={`intent ${item.intent}`}>{item.intent[0]?.toUpperCase()}</span>{item.intent}</td><td data-label="Volume">{compact(item.volume)}</td><td data-label="Difficulty"><span className="difficulty"><i style={{ width: `${Math.min(item.difficulty, 100)}%` }} /></span>{item.difficulty}</td><td data-label="CPC">€{item.cpc.toFixed(2)}</td><td data-label="Competition">{Math.round(item.competition * 100)}%</td></tr>)}</tbody></table></div></article></section>;
}

function KeywordGapView({ domain, connected }: { domain: string; connected: boolean }) {
  const [site, setSite] = useState(domain); const [competitor, setCompetitor] = useState("monday.com"); const [items, setItems] = useState<GapKeyword[]>(demoKeywords.map((item, index) => ({ ...item, competitorPosition: index + 3 }))); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const [live, setLive] = useState(false);
  async function analyse(event: React.FormEvent) { event.preventDefault(); setError(""); if (!connected) { setItems(demoKeywords.map((item, index) => ({ ...item, keyword: `${item.keyword} alternative`, competitorPosition: index + 2 }))); setLive(false); return; } setLoading(true); try { const response = await fetch(`/api/seo/gap?site=${encodeURIComponent(site)}&competitor=${encodeURIComponent(competitor)}`); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || "Keyword gap analysis failed."); setItems(payload.items); setLive(true); } catch (cause) { setError(cause instanceof Error ? cause.message : "Keyword gap analysis failed."); } finally { setLoading(false); } }
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">KEYWORD GAP</span><h1>Find keywords competitors own</h1><p>Compare two domains and uncover high-value queries where a competitor ranks but your site does not.</p></div></div><form className="dual-search" onSubmit={analyse}><label><span>Your domain</span><input value={site} onChange={(event) => setSite(event.target.value)} /></label><span className="versus">VS</span><label><span>Competitor</span><input value={competitor} onChange={(event) => setCompetitor(event.target.value)} /></label><button disabled={loading}>{loading ? "Comparing…" : "Find missing keywords"}</button></form>{error && <div className="audit-message error-message"><b>Comparison unavailable</b><span>{error}</span></div>}<SourceNote live={live}>{connected ? (live ? `Live gaps between ${site} and ${competitor}.` : "Run the comparison to retrieve live missing keywords.") : "The workflow works in sample mode until DataForSEO credentials are added."}</SourceNote><article className="panel data-panel"><div className="panel-head"><div><span className="panel-kicker">MISSING OPPORTUNITIES</span><h2>{items.length} keyword gaps</h2></div><button className="text-button" onClick={() => csv("rankscope-keyword-gap.csv", ["Keyword", "Intent", "Volume", "Difficulty", "CPC", "Competitor position"], items.map((item) => [item.keyword, item.intent, item.volume, item.difficulty, item.cpc, item.competitorPosition]))}>Export CSV</button></div><div className="table-wrap"><table><thead><tr><th>Missing keyword</th><th>Intent</th><th>Volume</th><th>Difficulty</th><th>Competitor pos.</th></tr></thead><tbody>{items.map((item) => <tr key={item.keyword}><td data-label="Keyword"><b>{item.keyword}</b></td><td data-label="Intent">{item.intent}</td><td data-label="Volume">{compact(item.volume)}</td><td data-label="Difficulty">{item.difficulty}</td><td data-label="Competitor position"><span className="position-pill">#{item.competitorPosition || "—"}</span></td></tr>)}</tbody></table></div></article></section>;
}

function RankTrackerView({ domain, connected }: { domain: string; connected: boolean }) {
  const [target, setTarget] = useState(domain); const [keyword, setKeyword] = useState("project management software"); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const [result, setResult] = useState<{ position: number | null; previous: number | null; url: string; checkedAt: string; live: boolean } | null>(null);
  async function check(event: React.FormEvent) { event.preventDefault(); setLoading(true); setError(""); try { const storageKey = `rankscope-rank:${cleanDomain(target)}:${keyword.toLowerCase()}`; const fallbackPrevious = typeof window !== "undefined" ? Number(localStorage.getItem(storageKey)) || null : null; let position: number | null; let url = ""; let checkedAt = new Date().toISOString(); if (connected) { const response = await fetch(`/api/seo/rank?domain=${encodeURIComponent(target)}&keyword=${encodeURIComponent(keyword)}`); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || "Position check failed."); position = payload.position; url = payload.url; checkedAt = payload.checkedAt; } else { position = 5 + (keyword.length % 18); url = `https://${cleanDomain(target)}/example-ranking-page`; } let previousValue = fallbackPrevious; const saved = await fetch("/api/workspace/rank", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ domain: target, keyword, position, url, checkedAt, source: connected ? "live" : "demo" }) }); if (saved.ok) { const savedPayload = await saved.json() as { previous?: number | null }; previousValue = typeof savedPayload.previous === "number" ? savedPayload.previous : null; if (typeof window !== "undefined") localStorage.removeItem(storageKey); } setResult({ position, previous: previousValue, url, checkedAt, live: connected }); } catch (cause) { setError(cause instanceof Error ? cause.message : "Position check failed."); } finally { setLoading(false); } }
  const movement = result?.position && result.previous ? result.previous - result.position : null;
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">POSITION TRACKING</span><h1>Check your Google ranking</h1><p>Run an on-demand mobile ranking check for Ireland and compare it with the last position saved in your workspace.</p></div></div><form className="dual-search rank-search" onSubmit={check}><label><span>Domain</span><input value={target} onChange={(event) => setTarget(event.target.value)} /></label><label><span>Keyword</span><input value={keyword} onChange={(event) => setKeyword(event.target.value)} /></label><button disabled={loading}>{loading ? "Checking…" : "Check position"}</button></form>{error && <div className="audit-message error-message"><b>Rank check unavailable</b><span>{error}</span></div>}{!result && <SourceNote live={false}>{connected ? "Ready to retrieve a fresh mobile Google position from DataForSEO." : "Sample rank checks work now; connect DataForSEO for live Google results."}</SourceNote>}{result && <section className="rank-result"><article className="rank-hero"><span>{result.live ? "LIVE MOBILE POSITION" : "DEMO POSITION"}</span><strong>{result.position ? `#${result.position}` : "100+"}</strong><p>{movement === null ? "First saved check" : movement > 0 ? `↑ ${movement} positions since last check` : movement < 0 ? `↓ ${Math.abs(movement)} positions since last check` : "No movement since last check"}</p></article><article className="panel rank-detail"><span className="panel-kicker">RANKING RESULT</span><h2>{keyword}</h2><p>{target} · Ireland · Mobile</p><a href={result.url || undefined} target="_blank" rel="noreferrer">{result.url || "No ranking URL found in the checked range"}</a><small>Checked {new Date(result.checkedAt).toLocaleString()}</small></article></section>}</section>;
}

function ContentBriefsView({ keywords }: { keywords: Keyword[] }) {
  const [topic, setTopic] = useState(keywords[0]?.keyword || "project management software"); const [audience, setAudience] = useState("small business teams"); const [brief, setBrief] = useState<{ title: string; secondary: string[]; outline: string[]; questions: string[] } | null>(null);
  function generate(event: React.FormEvent) { event.preventDefault(); const related = keywords.filter((item) => item.keyword !== topic).slice(0, 5).map((item) => item.keyword); setBrief({ title: `${topic[0]?.toUpperCase()}${topic.slice(1)}: A Practical Guide for ${audience}`, secondary: related.length ? related : [`best ${topic}`, `${topic} guide`, `${topic} comparison`], outline: [`What ${topic} means for ${audience}`, `Key benefits and use cases`, `How to choose the right approach`, `Step-by-step implementation`, `Common mistakes to avoid`, `Measurement and next steps`], questions: [`What is ${topic}?`, `How much does ${topic} cost?`, `What are the best ${topic} options?`, `How do you measure ${topic} results?`] }); }
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">SEO CONTENT BRIEFS</span><h1>Turn keyword data into a writing plan</h1><p>Create a structured, exportable brief using the latest keywords in your RankScope workspace.</p></div></div><form className="dual-search" onSubmit={generate}><label><span>Primary topic</span><input value={topic} onChange={(event) => setTopic(event.target.value)} /></label><label><span>Target audience</span><input value={audience} onChange={(event) => setAudience(event.target.value)} /></label><button>Generate brief</button></form><SourceNote live={false}>Briefs use the current keyword workspace. Run live Keyword Research first to ground secondary terms in provider data.</SourceNote>{!brief && <article className="panel audit-empty"><span className="action-icon">✦</span><div><h2>Ready to build a content brief</h2><p>Generate a title, keyword set, article structure and reader questions.</p></div></article>}{brief && <section className="brief-grid"><article className="panel brief-main"><span className="panel-kicker">RECOMMENDED TITLE</span><h2>{brief.title}</h2><div><span className="panel-kicker">ARTICLE OUTLINE</span><ol>{brief.outline.map((item) => <li key={item}>{item}</li>)}</ol></div></article><article className="panel brief-side"><span className="panel-kicker">SECONDARY KEYWORDS</span><div className="tag-list">{brief.secondary.map((item) => <span key={item}>{item}</span>)}</div><span className="panel-kicker questions-label">QUESTIONS TO ANSWER</span><ul>{brief.questions.map((item) => <li key={item}>{item}</li>)}</ul><button className="primary-button" onClick={() => csv("rankscope-content-brief.csv", ["Section", "Content"], [["Title", brief.title], ["Audience", audience], ["Secondary keywords", brief.secondary.join(" | ")], ...brief.outline.map((item, index) => [`H2 ${index + 1}`, item]), ["Questions", brief.questions.join(" | ")]])}>Export brief <span>↓</span></button></article></section>}</section>;
}

function CompetitorsView({ domain, connected, items, setItems }: { domain: string; connected: boolean; items: Competitor[]; setItems: (value: Competitor[]) => void }) {
  const [target, setTarget] = useState(domain); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const [live, setLive] = useState(false);
  async function analyse(event: React.FormEvent) { event.preventDefault(); setError(""); if (!connected) { setItems(demoCompetitors); setLive(false); return; } setLoading(true); try { const response = await fetch(`/api/seo/competitors?domain=${encodeURIComponent(target)}`); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || "Competitor research failed."); setItems(payload.items); setLive(true); } catch (cause) { setError(cause instanceof Error ? cause.message : "Competitor research failed."); } finally { setLoading(false); } }
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">COMPETITIVE RESEARCH</span><h1>Map your organic competitors</h1><p>See keyword overlap, estimated traffic and the domains competing for the same audience.</p></div></div><form className="tool-search" onSubmit={analyse}><input value={target} onChange={(event) => setTarget(event.target.value)} aria-label="Competitor research domain" placeholder="example.com" /><button disabled={loading}>{loading ? "Analysing…" : "Find competitors"}</button></form>{error && <div className="audit-message error-message"><b>Analysis unavailable</b><span>{error}</span></div>}<SourceNote live={live}>{connected ? (live ? "Current competitor estimates from DataForSEO." : "Run analysis to retrieve live competitor data.") : "Sample competitors are interactive until DataForSEO credentials are added."}</SourceNote><section className="competitor-grid">{items.map((item, index) => <article className="panel competitor-card" key={item.domain}><span className="rank">0{index + 1}</span><div><h2>{item.domain}</h2><p>{compact(item.intersections)} shared keywords</p></div><strong>{compact(item.traffic)}</strong><small>estimated traffic</small><div className="competitor-stats"><span><b>{compact(item.keywords)}</b> keywords</span><span><b>{item.averagePosition.toFixed(1)}</b> avg. position</span></div></article>)}</section><button className="secondary-button export-wide" onClick={() => csv("rankscope-competitors.csv", ["Domain", "Shared keywords", "Traffic", "Ranking keywords", "Average position"], items.map((item) => [item.domain, item.intersections, item.traffic, item.keywords, item.averagePosition]))}>Export competitor CSV</button></section>;
}

function BacklinksView({ domain, connected, summary, setSummary, domains, setDomains }: { domain: string; connected: boolean; summary: BacklinkSummary; setSummary: (value: BacklinkSummary) => void; domains: RefDomain[]; setDomains: (value: RefDomain[]) => void }) {
  const [target, setTarget] = useState(domain); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const [live, setLive] = useState(false);
  async function analyse(event: React.FormEvent) { event.preventDefault(); setError(""); if (!connected) { setSummary(demoBacklinks); setDomains(demoDomains); setLive(false); return; } setLoading(true); try { const response = await fetch(`/api/seo/backlinks?domain=${encodeURIComponent(target)}`); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || "Backlink analysis failed."); setSummary(payload.summary); setDomains(payload.domains); setLive(true); } catch (cause) { setError(cause instanceof Error ? cause.message : "Backlink analysis failed."); } finally { setLoading(false); } }
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">LINK INTELLIGENCE</span><h1>Understand your authority</h1><p>Inspect backlink volume, referring domains, link quality and broken-link opportunities.</p></div></div><form className="tool-search" onSubmit={analyse}><input value={target} onChange={(event) => setTarget(event.target.value)} aria-label="Backlink analysis domain" placeholder="example.com" /><button disabled={loading}>{loading ? "Analysing…" : "Analyse backlinks"}</button></form>{error && <div className="audit-message error-message"><b>Analysis unavailable</b><span>{error}</span></div>}<SourceNote live={live}>{connected ? (live ? "Current backlink index data from DataForSEO." : "Run analysis to retrieve the live backlink profile.") : "Sample backlink data remains available until DataForSEO is connected."}</SourceNote><section className="metric-grid backlink-metrics"><article className="metric-card"><div className="metric-top"><span>Domain rank</span></div><strong>{summary.rank}</strong></article><article className="metric-card"><div className="metric-top"><span>Backlinks</span></div><strong>{compact(summary.backlinks)}</strong></article><article className="metric-card"><div className="metric-top"><span>Referring domains</span></div><strong>{compact(summary.referringDomains)}</strong></article><article className="metric-card"><div className="metric-top"><span>Broken links</span></div><strong>{compact(summary.brokenBacklinks)}</strong></article></section><article className="panel data-panel"><div className="panel-head"><div><span className="panel-kicker">TOP SOURCES</span><h2>Referring domains</h2></div><button className="text-button" onClick={() => csv("rankscope-referring-domains.csv", ["Domain", "Rank", "Backlinks", "Dofollow", "First seen"], domains.map((item) => [item.domain, item.rank, item.backlinks, item.dofollow, item.firstSeen]))}>Export CSV</button></div><div className="table-wrap"><table><thead><tr><th>Domain</th><th>Rank</th><th>Backlinks</th><th>Dofollow</th><th>First seen</th></tr></thead><tbody>{domains.map((item) => <tr key={item.domain}><td data-label="Domain"><b>{item.domain}</b></td><td data-label="Rank">{item.rank}</td><td data-label="Backlinks">{compact(item.backlinks)}</td><td data-label="Dofollow">{compact(item.dofollow)}</td><td data-label="First seen">{item.firstSeen || "—"}</td></tr>)}</tbody></table></div></article></section>;
}

function PageSpeedAudit({ domain }: { domain: string }) {
  const [result, setResult] = useState<PageSpeedData | null>(null); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  async function runAudit() { setLoading(true); setError(""); try { const response = await fetch(`/api/pagespeed?url=${encodeURIComponent(domain)}`); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || "The audit could not be completed."); setResult(payload); } catch (cause) { setResult(null); setError(cause instanceof Error ? cause.message : "The audit could not be completed."); } finally { setLoading(false); } }
  return <section className="tool-view audit-view"><div className="tool-heading"><div><span className="panel-kicker">LIVE TECHNICAL SEO</span><h1>Measure the mobile experience</h1><p>Run a real Google PageSpeed Insights audit for <b>{domain}</b>.</p></div><button className="primary-button audit-run" onClick={runAudit} disabled={loading}>{loading ? "Running Google audit…" : result ? "Run again" : "Run live audit"}<span>→</span></button></div>{error && <div className="audit-message error-message"><b>Audit unavailable</b><span>{error}</span></div>}{!result && !error && <article className="panel audit-empty"><span className="action-icon">✓</span><div><h2>Ready for a live mobile audit</h2><p>Performance, accessibility, best practices, SEO and priority fixes will appear here.</p></div></article>}{result && <><SourceNote live={!result.fallback}>{result.fallback ? `${result.source} · ${result.notice}` : `Google PageSpeed Insights · ${new Date(result.fetchedAt).toLocaleString()}`}</SourceNote><section className="audit-score-grid">{Object.entries(result.scores).map(([key, value]) => <article className="metric-card" key={key}><div className="metric-top"><span>{key === "bestPractices" ? "Best practices" : key[0].toUpperCase() + key.slice(1)}</span><span className={result.fallback ? "demo-chip" : "live-source"}>{result.fallback ? "DEMO" : "LIVE"}</span></div><strong className={typeof value === "number" && value < 50 ? "score-low" : typeof value === "number" && value < 90 ? "score-mid" : "score-good"}>{value ?? "—"}</strong><p>Mobile Lighthouse score</p></article>)}</section><section className="module-grid"><article className="panel vital-panel"><div className="panel-head"><div><span className="panel-kicker">LAB METRICS</span><h2>Core performance signals</h2></div></div><div className="vital-grid"><div><span>Largest Contentful Paint</span><b>{result.metrics.lcp}</b></div><div><span>Cumulative Layout Shift</span><b>{result.metrics.cls}</b></div><div><span>Total Blocking Time</span><b>{result.metrics.tbt}</b></div></div></article><article className="panel audit-meta"><span className="panel-kicker">AUDIT DETAILS</span><h2>{new URL(result.url).hostname}</h2><p>Mobile strategy</p><small>{result.source}</small></article></section><article className="panel recommendations"><div className="panel-head"><div><span className="panel-kicker">PRIORITY FIXES</span><h2>Recommended improvements</h2></div></div><div className="recommendation-list">{result.opportunities.map((item, index) => <div key={item.id}><span>0{index + 1}</span><div><b>{item.title}</b><p>{item.detail}</p></div><em>{item.score ?? "—"}</em></div>)}</div></article></>}</section>;
}

function OnPageSeoView({ domain }: { domain: string }) {
  const [url, setUrl] = useState(domain); const [keyword, setKeyword] = useState("project management software"); const [result, setResult] = useState<OnPageResult | null>(null); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const [filter, setFilter] = useState<"All" | "Issues" | "Passed">("All");
  async function analyse(event: React.FormEvent) { event.preventDefault(); setLoading(true); setError(""); try { const response = await fetch(`/api/on-page?url=${encodeURIComponent(url)}&keyword=${encodeURIComponent(keyword)}`); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || "On-page analysis failed."); setResult(payload); } catch (cause) { setResult(null); setError(cause instanceof Error ? cause.message : "On-page analysis failed."); } finally { setLoading(false); } }
  const checks = result?.checks.filter((check) => filter === "All" || (filter === "Issues" ? !check.passed : check.passed)) || [];
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">ON-PAGE SEO CHECKER · NEW</span><h1>Turn any landing page into an action plan</h1><p>Fetch a live public page, inspect its content and technical signals, then prioritise the changes most likely to improve relevance.</p></div></div><form className="analysis-form" onSubmit={analyse}><label><span>Landing page URL</span><input value={url} onChange={(event) => setUrl(event.target.value)} placeholder="https://example.com/page" required /></label><label><span>Target keyword</span><input value={keyword} onChange={(event) => setKeyword(event.target.value)} placeholder="Target keyword" /></label><button disabled={loading}>{loading ? "Analysing page…" : "Analyse page"}</button></form>{error && <div className="audit-message error-message" role="alert"><b>Analysis unavailable</b><span>{error}</span></div>}{!result && !error && <article className="panel feature-empty"><span>◉</span><div><h2>Live HTML analysis is ready</h2><p>Check titles, descriptions, headings, keyword use, content depth, links, images, canonicals, mobile metadata and HTTPS.</p></div></article>}{result && <><SourceNote live>{result.source} · {new Date(result.analysedAt).toLocaleString()}</SourceNote><section className="score-layout"><article className="score-card panel"><div className={`score-orb ${result.score >= 80 ? "good" : result.score >= 60 ? "mid" : "low"}`} style={{ "--score": `${result.score}%` } as React.CSSProperties}><div><strong>{result.score}</strong><span>/100</span></div></div><div><span className="panel-kicker">ON-PAGE SCORE</span><h2>{new URL(result.url).hostname}</h2><p>{result.title || "No page title found"}</p></div></article><section className="mini-metric-grid"><div><span>Words</span><b>{result.metrics.words.toLocaleString()}</b></div><div><span>Headings</span><b>{result.h1s.length} H1 · {result.metrics.h2Count} H2</b></div><div><span>Links</span><b>{result.metrics.internalLinks} internal · {result.metrics.externalLinks} external</b></div><div><span>Images with alt</span><b>{result.metrics.imagesWithAlt}/{result.metrics.images}</b></div></section></section><article className="panel data-panel"><div className="panel-head responsive-head"><div><span className="panel-kicker">OPTIMISATION IDEAS</span><h2>{result.checks.filter((check) => !check.passed).length} actions to review</h2></div><div className="segmented">{(["All", "Issues", "Passed"] as const).map((item) => <button key={item} className={filter === item ? "active" : ""} onClick={() => setFilter(item)}>{item}</button>)}</div></div><div className="idea-list">{checks.map((check) => <div key={check.title}><span className={check.passed ? "check-state passed" : "check-state issue"}>{check.passed ? "✓" : "!"}</span><div><b>{check.title}</b><p>{check.category} · {check.detail}</p></div><em className={`impact-${check.impact.toLowerCase()}`}>{check.impact}</em></div>)}</div></article><section className="module-grid"><article className="panel"><span className="panel-kicker">SEARCH APPEARANCE</span><h2>{result.title || "Title missing"}</h2><p className="serp-url">{result.url}</p><p className="serp-description">{result.description || "Add a concise meta description that explains the page value and encourages the click."}</p></article><article className="panel technical-card"><span className="panel-kicker">TECHNICAL SIGNALS</span><dl><div><dt>Canonical</dt><dd>{result.technical.canonical || "Missing"}</dd></div><div><dt>Robots</dt><dd>{result.technical.robots}</dd></div><div><dt>Viewport</dt><dd>{result.technical.hasViewport ? "Present" : "Missing"}</dd></div></dl></article></section></>}</section>;
}

function buildTopicIdeas(topic: string) {
  const root = topic.trim() || "digital marketing";
  const patterns = [
    ["Complete guide", `The complete guide to ${root}`, "Guide"], ["Examples", `12 ${root} examples worth studying`, "List"],
    ["Strategy", `How to build a ${root} strategy`, "How-to"], ["Costs", `How much does ${root} cost?`, "Commercial"],
    ["Mistakes", `${root} mistakes that limit growth`, "Problem"], ["Comparison", `${root}: tools and approaches compared`, "Comparison"],
    ["Trends", `${root} trends shaping the next 12 months`, "Trend"], ["Measurement", `How to measure ${root} performance`, "Analytics"],
  ];
  return patterns.map(([label, headline, format], index) => ({ label, headline, format, volume: 420 + ((root.length * 173 + index * 719) % 6200), difficulty: 24 + ((root.length * 7 + index * 9) % 58), resonance: 92 - index * 5, question: index % 2 === 0 ? `What should beginners know about ${root}?` : `Which ${root} approach works best?` }));
}

function TopicResearchView() {
  const [topic, setTopic] = useState("project management"); const [location, setLocation] = useState("Ireland"); const [ideas, setIdeas] = useState(() => buildTopicIdeas("project management")); const [saved, setSaved] = useState<string[]>([]); const [sort, setSort] = useState("Resonance");
  function research(event: React.FormEvent) { event.preventDefault(); setIdeas(buildTopicIdeas(topic)); }
  const sorted = [...ideas].sort((a, b) => sort === "Volume" ? b.volume - a.volume : sort === "Difficulty" ? a.difficulty - b.difficulty : b.resonance - a.resonance);
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">TOPIC RESEARCH · NEW</span><h1>Find the angles your audience will care about</h1><p>Expand one subject into subtopics, headline directions, questions and content formats, then save the strongest ideas into your plan.</p></div></div><form className="analysis-form topic-form" onSubmit={research}><label><span>Core topic</span><input value={topic} onChange={(event) => setTopic(event.target.value)} required /></label><label><span>Market</span><select value={location} onChange={(event) => setLocation(event.target.value)}><option>Ireland</option><option>United Kingdom</option><option>United States</option><option>Global</option></select></label><button>Find topic ideas</button></form><div className="feature-toolbar"><SourceNote live={false}>Idea structures are available now; connect DataForSEO later for live volume and competitive SERP signals.</SourceNote><label>Sort by <select value={sort} onChange={(event) => setSort(event.target.value)}><option>Resonance</option><option>Volume</option><option>Difficulty</option></select></label></div><section className="topic-grid">{sorted.map((idea) => <article className="panel topic-card" key={idea.headline}><div className="topic-card-top"><span>{idea.label}</span><button aria-label={`Save ${idea.headline}`} className={saved.includes(idea.headline) ? "saved" : ""} onClick={() => setSaved((current) => current.includes(idea.headline) ? current.filter((item) => item !== idea.headline) : [...current, idea.headline])}>{saved.includes(idea.headline) ? "★" : "☆"}</button></div><h2>{idea.headline}</h2><p>{idea.question}</p><div className="topic-stats"><span><b>{compact(idea.volume)}</b> volume</span><span><b>{idea.difficulty}</b> difficulty</span><span><b>{idea.format}</b> format</span></div></article>)}</section><article className="architecture-card saved-ideas"><div><span className="panel-kicker">SAVED IDEAS · {location.toUpperCase()}</span><h2>{saved.length ? `${saved.length} ideas ready for briefing` : "Save promising topics as you research"}</h2></div>{saved.length > 0 && <button className="secondary-button" onClick={() => csv("rankscope-topic-ideas.csv", ["Topic", "Market"], saved.map((item) => [item, location]))}>Export saved ideas</button>}</article></section>;
}

function WritingAssistantView() {
  const [keyword, setKeyword] = useState("project management software"); const [tone, setTone] = useState("Professional"); const [target, setTarget] = useState(900); const [content, setContent] = useState("Project management software helps teams plan work, organise tasks and keep delivery visible. A useful platform should make priorities clear without adding unnecessary administration.\n\nStart by mapping the way your team currently works. Look for repeated handoffs, unclear ownership and reporting gaps. The right project management software should solve those problems while remaining simple enough for the whole team to adopt.");
  const words = content.trim() ? content.trim().split(/\s+/).length : 0; const sentences = content.split(/[.!?]+/).filter((item) => item.trim()).length; const paragraphs = content.split(/\n\s*\n/).filter((item) => item.trim()).length; const uses = keyword ? content.toLowerCase().split(keyword.toLowerCase()).length - 1 : 0; const averageSentence = sentences ? words / sentences : 0;
  const readability = Math.max(35, Math.min(100, Math.round(100 - Math.abs(17 - averageSentence) * 3))); const seo = Math.min(100, 45 + (uses > 0 ? 25 : 0) + (words >= Math.min(target, 300) ? 20 : Math.round(words / Math.max(target, 1) * 20)) + (paragraphs >= 2 ? 10 : 0)); const toneScore = Math.min(100, 68 + Math.min(paragraphs * 4, 16) + (averageSentence <= 22 ? 12 : 0)); const originality = Math.min(96, 70 + Math.min(26, new Set(content.toLowerCase().match(/[a-z]{5,}/g) || []).size)); const overall = Math.round((readability + seo + toneScore + originality) / 4);
  const checks = [{ label: "Target keyword used", pass: uses > 0 }, { label: `At least ${target.toLocaleString()} words`, pass: words >= target }, { label: "Short, readable sentences", pass: averageSentence > 0 && averageSentence <= 22 }, { label: "Scannable paragraphs", pass: paragraphs >= 3 }, { label: "Useful content depth", pass: words >= Math.min(500, target) }];
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">SEO WRITING ASSISTANT · NEW</span><h1>Improve content while you write</h1><p>Track SEO coverage, readability, originality signals and tone in real time, with clear recommendations alongside the draft.</p></div></div><section className="writer-settings panel"><label><span>Target keyword</span><input value={keyword} onChange={(event) => setKeyword(event.target.value)} /></label><label><span>Tone</span><select value={tone} onChange={(event) => setTone(event.target.value)}><option>Professional</option><option>Friendly</option><option>Expert</option><option>Conversational</option></select></label><label><span>Target length</span><input type="number" min="100" max="5000" step="100" value={target} onChange={(event) => setTarget(Number(event.target.value) || 100)} /></label></section><section className="writer-layout"><article className="panel editor-card"><div className="editor-toolbar"><span>{words.toLocaleString()} words · {sentences} sentences · {paragraphs} paragraphs</span><button onClick={() => setContent("")}>Clear</button></div><textarea aria-label="Content draft" value={content} onChange={(event) => setContent(event.target.value)} placeholder="Start writing or paste a draft…" /><div className="editor-footer"><span>Changes are analysed locally in your browser.</span><button className="secondary-button" onClick={() => csv("rankscope-writing-analysis.csv", ["Metric", "Value"], [["Overall", overall], ["SEO", seo], ["Readability", readability], ["Originality signals", originality], ["Tone", toneScore], ["Words", words], ["Keyword uses", uses]])}>Export analysis</button></div></article><aside className="writer-side"><article className="panel overall-card"><span className="panel-kicker">OVERALL SCORE</span><strong>{overall}</strong><span>/100</span><p>{overall >= 80 ? "Strong draft. Resolve the remaining recommendations before publishing." : "Keep improving the draft using the recommendations below."}</p></article><article className="panel score-list">{[["SEO", seo], ["Readability", readability], ["Originality signals", originality], [`${tone} tone`, toneScore]].map(([label, score]) => <div key={String(label)}><span>{label}</span><b>{score}</b><i><span style={{ width: `${score}%` }} /></i></div>)}</article><article className="panel writer-checks"><span className="panel-kicker">RECOMMENDATIONS</span>{checks.map((check) => <div key={check.label}><span className={check.pass ? "passed" : "issue"}>{check.pass ? "✓" : "!"}</span><p>{check.label}</p></div>)}</article></aside></section></section>;
}

function WorkspaceEnhancements({ view, domain, keywords, competitors, backlinks, domains, status }: { view: View; domain: string; keywords: Keyword[]; competitors: Competitor[]; backlinks: BacklinkSummary; domains: RefDomain[]; status: Status | null }) {
  const [done, setDone] = useState<string[]>([]); const [severity, setSeverity] = useState("All"); const [savedKeywords, setSavedKeywords] = useState<string[]>([]); const [reportSections, setReportSections] = useState(["Overview", "Keywords", "Competitors"]); const toggleDone = (item: string) => setDone((current) => current.includes(item) ? current.filter((value) => value !== item) : [...current, item]);
  if (["On-Page SEO", "Topic Research", "Writing Assistant"].includes(view)) return null;
  if (view === "Overview") { const tasks = ["Connect Search Console", "Review seven critical audit issues", "Add five priority keywords", "Recover broken backlinks"]; return <section className="enhancement-grid"><article className="panel"><div className="panel-head"><div><span className="panel-kicker">SEO ACTION PLAN</span><h2>{tasks.length - done.length} priority tasks remaining</h2></div><span className="completion-chip">{Math.round(done.length / tasks.length * 100)}%</span></div><div className="task-list">{tasks.map((task) => <label key={task} className={done.includes(task) ? "done" : ""}><input type="checkbox" checked={done.includes(task)} onChange={() => toggleDone(task)} /><span>{task}</span><em>{done.includes(task) ? "Done" : "To do"}</em></label>)}</div></article><article className="panel"><span className="panel-kicker">TOP ORGANIC PAGES</span><h2>Pages driving visibility</h2><div className="compact-rows">{[["/features", 6420, 18], ["/blog/productivity", 4180, 27], ["/pricing", 2960, 12], ["/templates", 1850, -4]].map(([page, visits, change]) => <div key={String(page)}><b>{page}</b><span>{compact(Number(visits))} visits</span><em className={Number(change) >= 0 ? "up" : "down"}>{Number(change) >= 0 ? "+" : ""}{change}%</em></div>)}</div></article></section>; }
  if (view === "Keywords") return <article className="panel data-panel enhancement-block"><div className="panel-head responsive-head"><div><span className="panel-kicker">KEYWORD MANAGER</span><h2>Build a prioritised keyword list</h2></div><span className="completion-chip">{savedKeywords.length} saved</span></div><div className="keyword-save-grid">{keywords.map((item) => <button key={item.keyword} className={savedKeywords.includes(item.keyword) ? "saved" : ""} onClick={() => setSavedKeywords((current) => current.includes(item.keyword) ? current.filter((value) => value !== item.keyword) : [...current, item.keyword])}><span>{savedKeywords.includes(item.keyword) ? "✓" : "+"}</span><b>{item.keyword}</b><em>{item.intent} · KD {item.difficulty}</em></button>)}</div></article>;
  if (view === "Keyword Gap") return <section className="enhancement-grid"><article className="panel gap-breakdown"><span className="panel-kicker">OVERLAP BREAKDOWN</span><h2>Opportunity types</h2>{[["Missing", 148, 72], ["Weak", 93, 48], ["Strong", 61, 32], ["Shared", 284, 88]].map(([label, value, width]) => <div key={String(label)}><span>{label}</span><i><span style={{ width: `${width}%` }} /></i><b>{value}</b></div>)}</article><article className="panel strategy-card"><span className="panel-kicker">NEXT BEST ACTION</span><h2>Start with commercial gaps below KD 50</h2><p>These terms combine buyer intent with attainable difficulty. Send the strongest candidates into Content Briefs, then monitor them in Rank Tracker.</p><button className="secondary-button">Mark strategy reviewed</button></article></section>;
  if (view === "Competitors") return <article className="panel enhancement-block"><div className="panel-head"><div><span className="panel-kicker">TRAFFIC SHARE</span><h2>Relative organic visibility</h2></div></div><div className="share-bars">{competitors.map((item) => { const max = Math.max(...competitors.map((value) => value.traffic)); return <div key={item.domain}><span>{item.domain}</span><i><span style={{ width: `${Math.max(6, item.traffic / max * 100)}%` }} /></i><b>{compact(item.traffic)}</b></div>; })}</div></article>;
  if (view === "Rank Tracker") return <article className="panel data-panel enhancement-block"><div className="panel-head responsive-head"><div><span className="panel-kicker">TRACKING CAMPAIGN</span><h2>Daily keyword portfolio</h2></div><div className="tag-list compact-tags"><span>Ireland</span><span>Mobile</span><span>Daily</span></div></div><div className="table-wrap"><table><thead><tr><th>Keyword</th><th>Position</th><th>Change</th><th>URL</th><th>SERP features</th></tr></thead><tbody>{keywords.slice(0, 5).map((item, index) => <tr key={item.keyword}><td data-label="Keyword"><b>{item.keyword}</b></td><td data-label="Position">#{7 + index * 3}</td><td data-label="Change"><span className={index === 3 ? "down" : "up"}>{index === 3 ? "−2" : `+${index + 1}`}</span></td><td data-label="URL">/{index ? "blog/guide" : "features"}</td><td data-label="SERP features">{index % 2 ? "FAQ · Images" : "Snippet · Sitelinks"}</td></tr>)}</tbody></table></div></article>;
  if (view === "Backlinks") return <section className="enhancement-grid"><article className="panel"><span className="panel-kicker">LINK HEALTH</span><h2>New, lost and potentially harmful links</h2><div className="link-health"><div><strong>+184</strong><span>New links</span></div><div><strong className="score-low">−37</strong><span>Lost links</span></div><div><strong>4.8%</strong><span>Potentially toxic</span></div></div></article><article className="panel"><span className="panel-kicker">TOP ANCHORS</span><h2>How sites describe {domain}</h2><div className="compact-rows">{[[domain, 38], ["project management", 24], ["website", 19], ["learn more", 11]].map(([anchor, share]) => <div key={String(anchor)}><b>{anchor}</b><i className="anchor-bar"><span style={{ width: `${share}%` }} /></i><em>{share}%</em></div>)}</div></article></section>;
  if (view === "Site Audit") { const issues = [{ level: "Error", issue: "4 pages return 4xx status codes", pages: 4 }, { level: "Error", issue: "3 pages have duplicate titles", pages: 3 }, { level: "Warning", issue: "18 images are missing alt text", pages: 12 }, { level: "Warning", issue: "11 pages have low text-to-HTML ratio", pages: 11 }, { level: "Notice", issue: "42 links use temporary redirects", pages: 24 }].filter((item) => severity === "All" || item.level === severity); return <article className="panel data-panel enhancement-block"><div className="panel-head responsive-head"><div><span className="panel-kicker">CRAWL ISSUES</span><h2>Page-level technical checks</h2></div><select className="filter-select" value={severity} onChange={(event) => setSeverity(event.target.value)}><option>All</option><option>Error</option><option>Warning</option><option>Notice</option></select></div><div className="table-wrap"><table><thead><tr><th>Severity</th><th>Issue</th><th>Affected pages</th><th>Status</th></tr></thead><tbody>{issues.map((item) => <tr key={item.issue}><td data-label="Severity"><span className={`severity-label ${item.level.toLowerCase()}`}>{item.level}</span></td><td data-label="Issue"><b>{item.issue}</b></td><td data-label="Affected pages">{item.pages}</td><td data-label="Status"><button className="row-action" onClick={() => toggleDone(item.issue)}>{done.includes(item.issue) ? "Resolved" : "Review"}</button></td></tr>)}</tbody></table></div></article>; }
  if (view === "Content Briefs") return <section className="enhancement-grid"><article className="panel"><span className="panel-kicker">CONTENT WORKFLOW</span><h2>Move briefs from idea to publication</h2><div className="kanban-mini">{[["Ideas", 8], ["Briefed", 4], ["Drafting", 2], ["Ready", 1]].map(([stage, count]) => <div key={String(stage)}><strong>{count}</strong><span>{stage}</span></div>)}</div></article><article className="panel"><span className="panel-kicker">CONTENT STANDARDS</span><h2>Default brief requirements</h2><div className="check-stack"><span>✓ Primary and secondary keywords</span><span>✓ Search intent and audience</span><span>✓ H2 structure and questions</span><span>✓ Internal-link recommendations</span></div></article></section>;
  if (view === "Reports") { const options = ["Overview", "Keywords", "Competitors", "Backlinks", "Site Audit"]; return <article className="panel report-builder"><div><span className="panel-kicker">CUSTOM REPORT BUILDER</span><h2>Choose the sections for a combined export</h2><p>Build a reusable executive report from the latest workspace data.</p></div><div className="report-options">{options.map((item) => <label key={item}><input type="checkbox" checked={reportSections.includes(item)} onChange={() => setReportSections((current) => current.includes(item) ? current.filter((value) => value !== item) : [...current, item])} /><span>{item}</span></label>)}</div><button className="primary-button" disabled={!reportSections.length} onClick={() => csv(`${domain}-seo-summary.csv`, ["Section", "Metric", "Value"], [["Overview", "Domain", domain], ["Overview", "Selected sections", reportSections.join(" | ")], ["Keywords", "Tracked opportunities", keywords.length], ["Competitors", "Compared domains", competitors.length], ["Backlinks", "Total links", backlinks.backlinks], ["Backlinks", "Referring domains", domains.length]])}>Generate combined report <span>↓</span></button></article>; }
  if (view === "Integrations") return <article className="panel data-panel enhancement-block"><div className="panel-head"><div><span className="panel-kicker">SYNC HEALTH</span><h2>Connector readiness</h2></div></div><div className="connector-health">{[["PageSpeed", status?.pageSpeed], ["Search Console", status?.searchConsole], ["GA4", status?.analytics], ["DataForSEO", status?.seoData]].map(([name, ready]) => <div key={String(name)}><span className={ready ? "online" : "offline"} /> <b>{name}</b><em>{ready ? "Ready" : "Awaiting credentials"}</em></div>)}</div></article>;
  return null;
}

function ReportsView({ domain, keywords, competitors, backlinks, domains }: { domain: string; keywords: Keyword[]; competitors: Competitor[]; backlinks: BacklinkSummary; domains: RefDomain[] }) {
  const reports = [
    { title: "Keyword opportunity report", copy: "Search demand, intent, CPC and difficulty.", action: () => csv(`${domain}-keywords.csv`, ["Keyword", "Intent", "Volume", "Difficulty", "CPC"], keywords.map((item) => [item.keyword, item.intent, item.volume, item.difficulty, item.cpc])) },
    { title: "Competitor landscape", copy: "Keyword overlap and estimated organic visibility.", action: () => csv(`${domain}-competitors.csv`, ["Domain", "Overlap", "Traffic", "Keywords"], competitors.map((item) => [item.domain, item.intersections, item.traffic, item.keywords])) },
    { title: "Backlink profile", copy: "Authority summary and strongest referring domains.", action: () => csv(`${domain}-backlinks.csv`, ["Metric", "Value"], [["Rank", backlinks.rank], ["Backlinks", backlinks.backlinks], ["Referring domains", backlinks.referringDomains], ["Broken backlinks", backlinks.brokenBacklinks], ...domains.map((item) => [item.domain, item.backlinks])]) },
  ];
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">REPORTING</span><h1>Export decision-ready SEO reports</h1><p>Download current workspace results as clean CSV files for analysis, client updates or planning.</p></div></div><div className="report-grid">{reports.map((report, index) => <article className="panel report-card" key={report.title}><span>0{index + 1}</span><h2>{report.title}</h2><p>{report.copy}</p><button className="primary-button" onClick={report.action}>Download CSV <b>↓</b></button></article>)}</div><article className="architecture-card"><span className="panel-kicker">REPORT STATUS</span><h2>{domain}</h2><p>Exports use the latest results visible in RankScope. After providers are connected, these reports automatically use live data.</p></article></section>;
}

function IntegrationsView({ status, onConfigure }: { status: Status | null; onConfigure: (value: string) => void }) {
  const items = [
    { name: "Google Search Console", ready: status?.searchConsole, copy: "Queries, clicks, impressions, CTR and position", mark: "G" },
    { name: "Google Analytics 4", ready: status?.analytics, copy: "Organic sessions, engagement and key events", mark: "A" },
    { name: "PageSpeed Insights", ready: status?.pageSpeed, copy: "Live Lighthouse scores and technical recommendations", mark: "P" },
    { name: "DataForSEO", ready: status?.seoData, copy: "Keyword, competitor and backlink intelligence", mark: "D" },
  ];
  return <section className="tool-view"><div className="tool-heading"><div><span className="panel-kicker">DATA SOURCES</span><h1>Connect every SEO signal</h1><p>Credentials stay on the server. The browser receives only normalised reporting data.</p></div></div><div className="integration-grid">{items.map((item) => <article className="integration-card" key={item.name}><div className="integration-mark">{item.mark}</div><div><div className="integration-title"><h2>{item.name}</h2><span className={item.ready ? "connected" : "waiting"}>{item.ready ? "Ready" : "Needs setup"}</span></div><p>{item.copy}</p><button className="secondary-button" onClick={() => onConfigure(item.name)}>{item.ready ? "View details" : "Setup instructions"}</button></div></article>)}</div><article className="architecture-card"><span className="panel-kicker">SECURE DATA FLOW</span><div className="data-flow"><div><b>Providers</b><span>GA4 · GSC · Google · DataForSEO</span></div><i>→</i><div><b>Protected endpoints</b><span>Credentials never reach the browser</span></div><i>→</i><div><b>RankScope</b><span>Normalised tools and exports</span></div></div></article></section>;
}

export default function Home() {
  const [view, setView] = useState<View>("Overview"); const [domain, setDomain] = useState("northstar.io"); const [query, setQuery] = useState("northstar.io"); const [period, setPeriod] = useState("30D"); const [menuOpen, setMenuOpen] = useState(false); const [dialog, setDialog] = useState<string | null>(null); const [status, setStatus] = useState<Status | null>(null);
  const [keywords, setKeywords] = useState(demoKeywords); const [competitors, setCompetitors] = useState(demoCompetitors); const [backlinkSummary, setBacklinkSummary] = useState(demoBacklinks); const [refDomains, setRefDomains] = useState(demoDomains); const [google, setGoogle] = useState<GoogleData>({}); const [syncing, setSyncing] = useState(false); const [syncError, setSyncError] = useState(""); const [workspacePersistence, setWorkspacePersistence] = useState<"loading" | "ready" | "unavailable">("loading"); const initials = useMemo(() => domain[0]?.toUpperCase() || "R", [domain]);
  useEffect(() => {
    let active = true;
    fetch("/api/integrations/status").then((response) => response.json()).then(setStatus).catch(() => setStatus(null));
    fetch("/api/workspace/state").then(async (response) => {
      if (!response.ok) throw new Error("Workspace storage is unavailable.");
      const payload = await response.json() as { snapshot?: WorkspaceSnapshot | null };
      if (!active) return;
      if (payload.snapshot) {
        const snapshot = payload.snapshot;
        setDomain(snapshot.domain); setQuery(snapshot.domain); setKeywords(snapshot.keywords); setCompetitors(snapshot.competitors); setBacklinkSummary(snapshot.backlinks); setRefDomains(snapshot.refDomains); setGoogle(snapshot.google || {});
      }
      setWorkspacePersistence("ready");
    }).catch(() => { if (active) setWorkspacePersistence("unavailable"); });
    return () => { active = false; };
  }, []);
  useEffect(() => {
    if (workspacePersistence !== "ready") return;
    const timer = window.setTimeout(() => {
      fetch("/api/workspace/state", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ domain, keywords, competitors, backlinks: backlinkSummary, refDomains, google }) }).catch(() => undefined);
    }, 700);
    return () => window.clearTimeout(timer);
  }, [workspacePersistence, domain, keywords, competitors, backlinkSummary, refDomains, google]);
  function analyse(event: React.FormEvent) { event.preventDefault(); const clean = cleanDomain(query); setDomain(clean); setQuery(clean); setView("Overview"); setGoogle({}); }
  async function syncGoogle() { setSyncing(true); setSyncError(""); try { const requests: Promise<Response>[] = []; const names: ("gsc" | "ga")[] = []; if (status?.searchConsole) { requests.push(fetch("/api/google/search-console")); names.push("gsc"); } if (status?.analytics) { requests.push(fetch("/api/google/analytics")); names.push("ga"); } const responses = await Promise.all(requests); const next: GoogleData = {}; for (let index = 0; index < responses.length; index++) { const payload = await responses[index].json(); if (!responses[index].ok) throw new Error(payload.error || "Google sync failed."); if (names[index] === "gsc") next.gsc = payload; else next.ga = payload; } setGoogle(next); } catch (cause) { setSyncError(cause instanceof Error ? cause.message : "Google sync failed."); } finally { setSyncing(false); } }
  function exportCurrent() { if (view === "Keywords") csv("rankscope-keywords.csv", ["Keyword", "Intent", "Volume", "Difficulty"], keywords.map((item) => [item.keyword, item.intent, item.volume, item.difficulty])); else if (view === "Competitors") csv("rankscope-competitors.csv", ["Domain", "Overlap", "Traffic"], competitors.map((item) => [item.domain, item.intersections, item.traffic])); else if (view === "Backlinks") csv("rankscope-backlinks.csv", ["Metric", "Value"], [["Backlinks", backlinkSummary.backlinks], ["Referring domains", backlinkSummary.referringDomains]]); else csv("rankscope-overview.csv", ["Domain", "Organic sessions", "Search clicks", "Impressions", "Key events"], [[domain, google.ga?.summary.sessions ?? 24800, google.gsc?.summary.clicks ?? 4281, google.gsc?.summary.impressions ?? 184600, google.ga?.summary.keyEvents ?? 386]]); }
  const setupCopy = dialog === "Google Search Console" ? "Add GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET, GOOGLE_REFRESH_TOKEN and GSC_SITE_URL. The Google token needs the webmasters.readonly scope." : dialog === "Google Analytics 4" ? "Add the same Google OAuth credentials plus GA4_PROPERTY_ID. The Google user or service account must have access to that property." : dialog === "PageSpeed Insights" ? "Live audits already work. GOOGLE_PAGESPEED_API_KEY is optional and provides higher, more consistent request limits." : dialog === "DataForSEO" ? "Add DATAFORSEO_LOGIN and DATAFORSEO_PASSWORD as protected environment values. Keywords, competitors and backlinks switch to live mode automatically." : "Add the provider credentials as protected environment values.";
  return <main className={menuOpen ? "app-shell menu-visible" : "app-shell"}>{menuOpen && <button className="menu-backdrop" aria-label="Close navigation" onClick={() => setMenuOpen(false)} />}<aside id="primary-navigation" className={menuOpen ? "sidebar open" : "sidebar"}><div className="brand"><span className="brand-mark"><i /><i /><i /></span><span>RankScope</span><button className="drawer-close" aria-label="Close menu" onClick={() => setMenuOpen(false)}>×</button></div><nav>{navItems.map((item) => <button key={item.label} onClick={() => { setView(item.label); setMenuOpen(false); }} className={view === item.label ? "active" : ""}><span className="nav-icon">{item.icon}</span>{item.label}{["Site Audit", "On-Page SEO"].includes(item.label) && <em>LIVE</em>}</button>)}</nav><div className="sidebar-foot"><div className="usage"><div><span>Provider mode</span><b>{status?.seoData ? "Live" : "Demo"}</b></div><i><span style={{ width: `${[status?.pageSpeed, status?.searchConsole, status?.analytics, status?.seoData].filter(Boolean).length * 25}%` }} /></i><small>{[status?.pageSpeed, status?.searchConsole, status?.analytics, status?.seoData].filter(Boolean).length} of 4 sources ready</small></div><div className="profile"><span>{initials}</span><div><b>Andrew</b><small>Workspace owner</small></div></div></div></aside><section className="workspace"><header className="topbar"><div className="mobile-topline"><button className="menu-button" onClick={() => setMenuOpen(!menuOpen)} aria-label="Open menu" aria-expanded={menuOpen} aria-controls="primary-navigation">☰</button><span className="mobile-brand"><span className="brand-mark"><i /><i /><i /></span>RankScope</span></div><form className="domain-search" onSubmit={analyse}><span>⌕</span><input aria-label="Domain to analyse" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Enter any domain" /><button>Analyse</button></form><div className="top-actions"><button aria-label="Data sources" onClick={() => setView("Integrations")}>◇<i /></button><button className="export" onClick={exportCurrent}>Export CSV</button></div></header><div className="content">{view === "Overview" && <Overview domain={domain} period={period} setPeriod={setPeriod} status={status} google={google} syncing={syncing} syncError={syncError} sync={syncGoogle} />}{view === "Keywords" && <KeywordsView connected={Boolean(status?.seoData)} items={keywords} setItems={setKeywords} />}{view === "Keyword Gap" && <KeywordGapView domain={domain} connected={Boolean(status?.seoData)} />}{view === "Competitors" && <CompetitorsView domain={domain} connected={Boolean(status?.seoData)} items={competitors} setItems={setCompetitors} />}{view === "Rank Tracker" && <RankTrackerView domain={domain} connected={Boolean(status?.seoData)} />}{view === "Backlinks" && <BacklinksView domain={domain} connected={Boolean(status?.seoData)} summary={backlinkSummary} setSummary={setBacklinkSummary} domains={refDomains} setDomains={setRefDomains} />}{view === "Site Audit" && <PageSpeedAudit domain={domain} />}{view === "On-Page SEO" && <OnPageSeoView domain={domain} />}{view === "Topic Research" && <TopicResearchView />}{view === "Writing Assistant" && <WritingAssistantView />}{view === "Content Briefs" && <ContentBriefsView keywords={keywords} />}{view === "Reports" && <ReportsView domain={domain} keywords={keywords} competitors={competitors} backlinks={backlinkSummary} domains={refDomains} />}{view === "Integrations" && <IntegrationsView status={status} onConfigure={setDialog} />}<WorkspaceEnhancements view={view} domain={domain} keywords={keywords} competitors={competitors} backlinks={backlinkSummary} domains={refDomains} status={status} /></div></section>{dialog && <div className="modal-backdrop" onMouseDown={() => setDialog(null)}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" onMouseDown={(event) => event.stopPropagation()}><span className="modal-handle" /><button className="modal-close" onClick={() => setDialog(null)} aria-label="Close dialog">×</button><span className="panel-kicker">CONNECTION DETAILS</span><h2 id="modal-title">{dialog}</h2><p>{setupCopy}</p><button className="primary-button" onClick={() => setDialog(null)}>Close <span>→</span></button><small>Private provider credentials are never sent to the browser.</small></div></div>}</main>;
}
